"""Order fulfillment SQLite service."""

from __future__ import annotations

import math
import sqlite3
from pathlib import Path
from typing import Any, Callable


class OrderError(Exception):
    """Stable order-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        self.code = code
        self.message = message
        self.details: dict[str, object] = details if details is not None else {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


def _is_finite_number(value: object) -> bool:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return False
    return math.isfinite(float(value))


def _require_nonempty_str(value: object, field: str) -> str:
    if not isinstance(value, str) or value == "" or value.strip() == "":
        raise OrderError(
            "INVALID_INPUT",
            f"invalid {field}",
            {"field": field},
        )
    return value


def _require_int(value: object, field: str, *, min_value: int | None = None) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise OrderError(
            "INVALID_INPUT",
            f"invalid {field}",
            {"field": field},
        )
    if min_value is not None and value < min_value:
        raise OrderError(
            "INVALID_INPUT",
            f"invalid {field}",
            {"field": field},
        )
    return value


def _read_clock(clock: Callable[[], Any]) -> float | int:
    try:
        now = clock()
    except Exception as exc:  # noqa: BLE001 - dependency boundary
        raise OrderError(
            "INVALID_DEPENDENCY",
            "clock raised",
            {"dependency": "clock", "error": str(exc)},
        ) from exc
    if not _is_finite_number(now):
        raise OrderError(
            "INVALID_DEPENDENCY",
            "clock must return a finite number",
            {"dependency": "clock"},
        )
    return now


def _read_id(id_factory: Callable[[], Any]) -> str:
    try:
        value = id_factory()
    except Exception as exc:  # noqa: BLE001 - dependency boundary
        raise OrderError(
            "INVALID_DEPENDENCY",
            "id_factory raised",
            {"dependency": "id_factory", "error": str(exc)},
        ) from exc
    if not isinstance(value, str) or value == "" or value.strip() == "":
        raise OrderError(
            "INVALID_DEPENDENCY",
            "id_factory must return a non-empty string",
            {"dependency": "id_factory"},
        )
    return value


def _validate_items(items: object) -> list[tuple[str, int, int]]:
    if not isinstance(items, list) or len(items) == 0:
        raise OrderError("INVALID_INPUT", "items must be a non-empty list", {"field": "items"})
    seen: set[str] = set()
    canonical: list[tuple[str, int, int]] = []
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise OrderError(
                "INVALID_INPUT",
                "item must be an object",
                {"field": "items", "index": idx},
            )
        if set(item.keys()) != {"sku", "quantity", "unit_price_cents"}:
            raise OrderError(
                "INVALID_INPUT",
                "item fields must be exactly sku, quantity, unit_price_cents",
                {"field": "items", "index": idx},
            )
        sku = _require_nonempty_str(item["sku"], "sku")
        if sku in seen:
            raise OrderError(
                "INVALID_INPUT",
                "duplicate sku in items",
                {"field": "items", "sku": sku},
            )
        seen.add(sku)
        quantity = _require_int(item["quantity"], "quantity", min_value=1)
        unit_price = _require_int(item["unit_price_cents"], "unit_price_cents", min_value=0)
        canonical.append((sku, quantity, unit_price))
    canonical.sort(key=lambda t: t[0])
    return canonical


class OrderService:
    """SQLite-backed order service."""

    _SCHEMA_VERSION = "1"

    def __init__(self, db_path, *, clock, id_factory):
        if not callable(clock) or not callable(id_factory):
            raise OrderError("INVALID_INPUT", "clock and id_factory must be callable")
        self._db_path = str(db_path)
        self._clock = clock
        self._id_factory = id_factory
        parent = Path(self._db_path).parent
        if str(parent) not in ("", "."):
            parent.mkdir(parents=True, exist_ok=True)
        self._init_schema()

    def _connect(self) -> sqlite3.Connection:
        try:
            conn = sqlite3.connect(self._db_path, isolation_level=None, timeout=30.0)
            conn.row_factory = sqlite3.Row
            conn.execute("PRAGMA foreign_keys = ON")
            return conn
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", f"failed to open database: {exc}") from exc

    def _init_schema(self) -> None:
        conn = self._connect()
        try:
            try:
                conn.execute("BEGIN IMMEDIATE")
                tables = {
                    row["name"]
                    for row in conn.execute(
                        "SELECT name FROM sqlite_master WHERE type='table'"
                    )
                }
                if not tables:
                    self._create_schema(conn)
                    conn.execute("COMMIT")
                    return
                self._validate_schema(conn, tables)
                conn.execute("COMMIT")
            except OrderError:
                conn.execute("ROLLBACK")
                raise
            except sqlite3.Error as exc:
                conn.execute("ROLLBACK")
                raise OrderError("STORAGE_ERROR", f"schema init failed: {exc}") from exc
        finally:
            conn.close()

    def _create_schema(self, conn: sqlite3.Connection) -> None:
        conn.executescript(
            """
            CREATE TABLE meta (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );
            CREATE TABLE stock (
                sku TEXT PRIMARY KEY,
                available INTEGER NOT NULL CHECK (available >= 0)
            );
            CREATE TABLE orders (
                order_id TEXT PRIMARY KEY,
                idempotency_key TEXT NOT NULL UNIQUE,
                status TEXT NOT NULL CHECK (status IN ('pending','paid','shipped','cancelled')),
                total_cents INTEGER NOT NULL CHECK (total_cents >= 0),
                payment_id TEXT,
                amount_paid_cents INTEGER,
                created_at REAL NOT NULL,
                updated_at REAL NOT NULL
            );
            CREATE TABLE order_items (
                order_id TEXT NOT NULL,
                sku TEXT NOT NULL,
                quantity INTEGER NOT NULL CHECK (quantity > 0),
                unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),
                PRIMARY KEY (order_id, sku),
                FOREIGN KEY (order_id) REFERENCES orders(order_id)
            );
            CREATE UNIQUE INDEX idx_orders_payment_id
                ON orders(payment_id) WHERE payment_id IS NOT NULL;
            """
        )
        conn.execute(
            "INSERT INTO meta(key, value) VALUES ('schema_version', ?)",
            (self._SCHEMA_VERSION,),
        )

    def _validate_schema(self, conn: sqlite3.Connection, tables: set[str]) -> None:
        required = {"meta", "stock", "orders", "order_items"}
        if not required.issubset(tables):
            raise OrderError(
                "SCHEMA_MISMATCH",
                "incompatible database schema",
                {"tables": sorted(tables)},
            )
        try:
            row = conn.execute(
                "SELECT value FROM meta WHERE key = 'schema_version'"
            ).fetchone()
        except sqlite3.Error as exc:
            raise OrderError("SCHEMA_MISMATCH", "missing schema metadata") from exc
        if row is None or row["value"] != self._SCHEMA_VERSION:
            raise OrderError(
                "SCHEMA_MISMATCH",
                "unknown or incompatible schema_version",
                {"schema_version": None if row is None else row["value"]},
            )
        # Probe expected columns exist.
        try:
            conn.execute("SELECT sku, available FROM stock LIMIT 0")
            conn.execute(
                "SELECT order_id, idempotency_key, status, total_cents, payment_id, "
                "amount_paid_cents, created_at, updated_at FROM orders LIMIT 0"
            )
            conn.execute(
                "SELECT order_id, sku, quantity, unit_price_cents FROM order_items LIMIT 0"
            )
        except sqlite3.Error as exc:
            raise OrderError("SCHEMA_MISMATCH", "incompatible column layout") from exc

    def _load_order(self, conn: sqlite3.Connection, order_id: str) -> dict[str, Any]:
        row = conn.execute(
            "SELECT * FROM orders WHERE order_id = ?", (order_id,)
        ).fetchone()
        if row is None:
            raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})
        items = conn.execute(
            "SELECT sku, quantity, unit_price_cents FROM order_items "
            "WHERE order_id = ? ORDER BY sku ASC",
            (order_id,),
        ).fetchall()
        return {
            "order_id": row["order_id"],
            "idempotency_key": row["idempotency_key"],
            "status": row["status"],
            "items": [
                {
                    "sku": it["sku"],
                    "quantity": int(it["quantity"]),
                    "unit_price_cents": int(it["unit_price_cents"]),
                }
                for it in items
            ],
            "total_cents": int(row["total_cents"]),
            "payment_id": row["payment_id"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        }

    def set_stock(self, sku: str, quantity: int) -> dict:
        sku = _require_nonempty_str(sku, "sku")
        quantity = _require_int(quantity, "quantity", min_value=0)
        conn = self._connect()
        try:
            try:
                conn.execute("BEGIN IMMEDIATE")
                conn.execute(
                    "INSERT INTO stock(sku, available) VALUES (?, ?) "
                    "ON CONFLICT(sku) DO UPDATE SET available = excluded.available",
                    (sku, quantity),
                )
                row = conn.execute(
                    "SELECT available FROM stock WHERE sku = ?", (sku,)
                ).fetchone()
                conn.execute("COMMIT")
                return {"sku": sku, "available": int(row["available"])}
            except OrderError:
                conn.execute("ROLLBACK")
                raise
            except sqlite3.Error as exc:
                conn.execute("ROLLBACK")
                raise OrderError("STORAGE_ERROR", f"set_stock failed: {exc}") from exc
        finally:
            conn.close()

    def create_order(self, idempotency_key: str, items: list[dict]) -> dict:
        idempotency_key = _require_nonempty_str(idempotency_key, "idempotency_key")
        canonical = _validate_items(items)
        total_cents = sum(q * p for _, q, p in canonical)

        conn = self._connect()
        try:
            try:
                conn.execute("BEGIN IMMEDIATE")
                existing = conn.execute(
                    "SELECT order_id FROM orders WHERE idempotency_key = ?",
                    (idempotency_key,),
                ).fetchone()
                if existing is not None:
                    order = self._load_order(conn, existing["order_id"])
                    existing_items = [
                        (it["sku"], it["quantity"], it["unit_price_cents"])
                        for it in order["items"]
                    ]
                    if existing_items != canonical:
                        raise OrderError(
                            "IDEMPOTENCY_CONFLICT",
                            "idempotency key reused with different items",
                            {"idempotency_key": idempotency_key},
                        )
                    conn.execute("COMMIT")
                    return order

                # Reserve stock for all SKUs or none.
                for sku, quantity, _ in canonical:
                    row = conn.execute(
                        "SELECT available FROM stock WHERE sku = ?", (sku,)
                    ).fetchone()
                    if row is None or int(row["available"]) < quantity:
                        raise OrderError(
                            "INSUFFICIENT_STOCK",
                            "insufficient stock",
                            {"sku": sku},
                        )

                order_id: str | None = None
                for attempt in range(3):
                    candidate = _read_id(self._id_factory)
                    clash = conn.execute(
                        "SELECT 1 FROM orders WHERE order_id = ?", (candidate,)
                    ).fetchone()
                    if clash is None:
                        order_id = candidate
                        break
                if order_id is None:
                    raise OrderError(
                        "ID_COLLISION",
                        "unable to allocate unique order id",
                        {},
                    )

                now = _read_clock(self._clock)
                conn.execute(
                    "INSERT INTO orders("
                    "order_id, idempotency_key, status, total_cents, payment_id, "
                    "amount_paid_cents, created_at, updated_at"
                    ") VALUES (?, ?, 'pending', ?, NULL, NULL, ?, ?)",
                    (order_id, idempotency_key, total_cents, now, now),
                )
                for sku, quantity, unit_price in canonical:
                    conn.execute(
                        "INSERT INTO order_items(order_id, sku, quantity, unit_price_cents) "
                        "VALUES (?, ?, ?, ?)",
                        (order_id, sku, quantity, unit_price),
                    )
                    cur = conn.execute(
                        "UPDATE stock SET available = available - ? "
                        "WHERE sku = ? AND available >= ?",
                        (quantity, sku, quantity),
                    )
                    if cur.rowcount != 1:
                        raise OrderError(
                            "INSUFFICIENT_STOCK",
                            "insufficient stock",
                            {"sku": sku},
                        )

                order = self._load_order(conn, order_id)
                conn.execute("COMMIT")
                return order
            except OrderError:
                conn.execute("ROLLBACK")
                raise
            except sqlite3.Error as exc:
                conn.execute("ROLLBACK")
                raise OrderError("STORAGE_ERROR", f"create_order failed: {exc}") from exc
        finally:
            conn.close()

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        order_id = _require_nonempty_str(order_id, "order_id")
        payment_id = _require_nonempty_str(payment_id, "payment_id")
        amount_cents = _require_int(amount_cents, "amount_cents", min_value=0)

        conn = self._connect()
        try:
            try:
                conn.execute("BEGIN IMMEDIATE")
                row = conn.execute(
                    "SELECT * FROM orders WHERE order_id = ?", (order_id,)
                ).fetchone()
                if row is None:
                    raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})

                status = row["status"]
                if status != "pending":
                    if (
                        row["payment_id"] == payment_id
                        and row["amount_paid_cents"] is not None
                        and int(row["amount_paid_cents"]) == amount_cents
                    ):
                        order = self._load_order(conn, order_id)
                        conn.execute("COMMIT")
                        return order
                    if row["payment_id"] is not None:
                        raise OrderError(
                            "PAYMENT_CONFLICT",
                            "payment conflicts with existing payment",
                            {"order_id": order_id, "payment_id": payment_id},
                        )
                    raise OrderError(
                        "INVALID_STATE",
                        f"cannot pay order in status {status}",
                        {"order_id": order_id, "status": status},
                    )

                if int(row["total_cents"]) != amount_cents:
                    raise OrderError(
                        "AMOUNT_MISMATCH",
                        "amount_cents does not match order total",
                        {
                            "order_id": order_id,
                            "expected": int(row["total_cents"]),
                            "got": amount_cents,
                        },
                    )

                other = conn.execute(
                    "SELECT order_id FROM orders WHERE payment_id = ? AND order_id != ?",
                    (payment_id, order_id),
                ).fetchone()
                if other is not None:
                    raise OrderError(
                        "PAYMENT_CONFLICT",
                        "payment_id already used for another order",
                        {"payment_id": payment_id},
                    )

                now = _read_clock(self._clock)
                try:
                    conn.execute(
                        "UPDATE orders SET status = 'paid', payment_id = ?, "
                        "amount_paid_cents = ?, updated_at = ? WHERE order_id = ?",
                        (payment_id, amount_cents, now, order_id),
                    )
                except sqlite3.IntegrityError as exc:
                    raise OrderError(
                        "PAYMENT_CONFLICT",
                        "payment_id already used",
                        {"payment_id": payment_id},
                    ) from exc

                order = self._load_order(conn, order_id)
                conn.execute("COMMIT")
                return order
            except OrderError:
                conn.execute("ROLLBACK")
                raise
            except sqlite3.Error as exc:
                conn.execute("ROLLBACK")
                raise OrderError("STORAGE_ERROR", f"pay_order failed: {exc}") from exc
        finally:
            conn.close()

    def cancel_order(self, order_id: str) -> dict:
        order_id = _require_nonempty_str(order_id, "order_id")
        conn = self._connect()
        try:
            try:
                conn.execute("BEGIN IMMEDIATE")
                row = conn.execute(
                    "SELECT * FROM orders WHERE order_id = ?", (order_id,)
                ).fetchone()
                if row is None:
                    raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})
                status = row["status"]
                if status == "cancelled":
                    order = self._load_order(conn, order_id)
                    conn.execute("COMMIT")
                    return order
                if status == "shipped":
                    raise OrderError(
                        "INVALID_STATE",
                        "cannot cancel shipped order",
                        {"order_id": order_id, "status": status},
                    )
                if status not in ("pending", "paid"):
                    raise OrderError(
                        "INVALID_STATE",
                        f"cannot cancel order in status {status}",
                        {"order_id": order_id, "status": status},
                    )

                items = conn.execute(
                    "SELECT sku, quantity FROM order_items WHERE order_id = ?",
                    (order_id,),
                ).fetchall()
                for it in items:
                    conn.execute(
                        "INSERT INTO stock(sku, available) VALUES (?, ?) "
                        "ON CONFLICT(sku) DO UPDATE SET available = available + excluded.available",
                        (it["sku"], int(it["quantity"])),
                    )

                now = _read_clock(self._clock)
                conn.execute(
                    "UPDATE orders SET status = 'cancelled', updated_at = ? WHERE order_id = ?",
                    (now, order_id),
                )
                order = self._load_order(conn, order_id)
                conn.execute("COMMIT")
                return order
            except OrderError:
                conn.execute("ROLLBACK")
                raise
            except sqlite3.Error as exc:
                conn.execute("ROLLBACK")
                raise OrderError("STORAGE_ERROR", f"cancel_order failed: {exc}") from exc
        finally:
            conn.close()

    def ship_order(self, order_id: str) -> dict:
        order_id = _require_nonempty_str(order_id, "order_id")
        conn = self._connect()
        try:
            try:
                conn.execute("BEGIN IMMEDIATE")
                row = conn.execute(
                    "SELECT * FROM orders WHERE order_id = ?", (order_id,)
                ).fetchone()
                if row is None:
                    raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})
                status = row["status"]
                if status == "shipped":
                    order = self._load_order(conn, order_id)
                    conn.execute("COMMIT")
                    return order
                if status != "paid":
                    raise OrderError(
                        "INVALID_STATE",
                        f"cannot ship order in status {status}",
                        {"order_id": order_id, "status": status},
                    )
                now = _read_clock(self._clock)
                conn.execute(
                    "UPDATE orders SET status = 'shipped', updated_at = ? WHERE order_id = ?",
                    (now, order_id),
                )
                order = self._load_order(conn, order_id)
                conn.execute("COMMIT")
                return order
            except OrderError:
                conn.execute("ROLLBACK")
                raise
            except sqlite3.Error as exc:
                conn.execute("ROLLBACK")
                raise OrderError("STORAGE_ERROR", f"ship_order failed: {exc}") from exc
        finally:
            conn.close()

    def get_order(self, order_id: str) -> dict:
        order_id = _require_nonempty_str(order_id, "order_id")
        conn = self._connect()
        try:
            try:
                conn.execute("BEGIN IMMEDIATE")
                order = self._load_order(conn, order_id)
                conn.execute("COMMIT")
                return order
            except OrderError:
                conn.execute("ROLLBACK")
                raise
            except sqlite3.Error as exc:
                conn.execute("ROLLBACK")
                raise OrderError("STORAGE_ERROR", f"get_order failed: {exc}") from exc
        finally:
            conn.close()


__all__ = ["OrderError", "OrderService"]

