"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time
import uuid
from typing import Any

from src.order_fulfillment import OrderError, OrderService


def _emit(payload: dict[str, Any], exit_code: int) -> None:
    sys.stdout.write(
        json.dumps(payload, sort_keys=True, separators=(",", ":"), allow_nan=False)
        + "\n"
    )
    sys.stdout.flush()
    raise SystemExit(exit_code)


def _error_payload(code: str, message: str, details: dict[str, object] | None = None) -> dict:
    return {
        "ok": False,
        "error": {
            "code": code,
            "message": message,
            "details": details if details is not None else {},
        },
    }


def _read_input(command: str) -> dict[str, Any]:
    raw = sys.stdin.readline()
    if raw == "":
        if command in ("init", "recover", "list"):
            return {}
        # stock/create/pay/cancel/ship/get always need input, but empty line
        # for omitted stdin on commands that allow {} is only init/recover/list.
        # For order CLI only create-like commands; empty means {}.
        # Contract: "except init, recover, and list" — order package has no those.
        # Non-empty line required generally; empty stdin line for missing may be {}.
        # Treat completely missing/empty as invalid for order commands that need fields
        # unless we get "{}". Empty string from EOF: treat as {}.
        return {}
    line = raw if raw.endswith("\n") else raw
    text = line.strip("\n")
    if text == "":
        return {}
    try:
        value = json.loads(text)
    except json.JSONDecodeError:
        raise OrderError("INVALID_INPUT", "stdin must be valid JSON object") from None
    if not isinstance(value, dict):
        raise OrderError("INVALID_INPUT", "stdin must be a JSON object")
    return value


def _require_fields(data: dict[str, Any], fields: list[str]) -> None:
    missing = [f for f in fields if f not in data]
    if missing:
        raise OrderError(
            "INVALID_INPUT",
            "missing required fields",
            {"missing": missing},
        )
    unknown = [k for k in data.keys() if k not in fields]
    if unknown:
        raise OrderError(
            "INVALID_INPUT",
            "unknown fields",
            {"unknown": unknown},
        )


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(prog="order_fulfillment", add_help=True)
    parser.add_argument("--db", required=True)
    parser.add_argument(
        "command",
        choices=["stock", "create", "pay", "cancel", "ship", "get"],
    )
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        # argparse already wrote help/error to stderr; map to protocol if needed
        code = int(exc.code) if isinstance(exc.code, int) else 2
        if code == 0:
            raise
        _emit(_error_payload("INVALID_INPUT", "invalid CLI arguments"), 2)

    try:
        data = _read_input(args.command)
        service = OrderService(
            args.db,
            clock=time.time,
            id_factory=lambda: uuid.uuid4().hex,
        )
        if args.command == "stock":
            _require_fields(data, ["sku", "quantity"])
            result = service.set_stock(data["sku"], data["quantity"])
        elif args.command == "create":
            _require_fields(data, ["idempotency_key", "items"])
            result = service.create_order(data["idempotency_key"], data["items"])
        elif args.command == "pay":
            _require_fields(data, ["order_id", "payment_id", "amount_cents"])
            result = service.pay_order(
                data["order_id"], data["payment_id"], data["amount_cents"]
            )
        elif args.command == "cancel":
            _require_fields(data, ["order_id"])
            result = service.cancel_order(data["order_id"])
        elif args.command == "ship":
            _require_fields(data, ["order_id"])
            result = service.ship_order(data["order_id"])
        elif args.command == "get":
            _require_fields(data, ["order_id"])
            result = service.get_order(data["order_id"])
        else:
            raise OrderError("INVALID_INPUT", "unknown command")
        _emit({"ok": True, "result": result}, 0)
    except OrderError as exc:
        exit_code = 3 if exc.code == "STORAGE_ERROR" else 2
        _emit(_error_payload(exc.code, exc.message, exc.details), exit_code)
    except Exception as exc:  # noqa: BLE001 - CLI envelope
        _emit(
            _error_payload("STORAGE_ERROR", f"unexpected failure: {exc}", {}),
            3,
        )


if __name__ == "__main__":
    main()

