"""Filesystem-backed durable delivery spool."""

from __future__ import annotations

import dataclasses
import json
import math
import os
import secrets
import sys
import time
import uuid
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable


@dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        self.code = code
        self.message = message
        self.details: dict[str, object] = details if details is not None else {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


def _is_bool(value: object) -> bool:
    return isinstance(value, bool)


def _is_finite_number(value: object) -> bool:
    if _is_bool(value) or not isinstance(value, (int, float)):
        return False
    return math.isfinite(float(value))


def _require_positive_int(value: object, field: str) -> int:
    if _is_bool(value) or not isinstance(value, int) or value <= 0:
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    return value


def _require_nonneg_number(value: object, field: str, *, positive: bool = False) -> float:
    if not _is_finite_number(value):
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    num = float(value) if isinstance(value, float) else value
    if positive and not (num > 0):
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    if not positive and num < 0:
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    return value  # type: ignore[return-value]


def _require_nonempty_str(value: object, field: str) -> str:
    if not isinstance(value, str) or value == "" or value.strip() == "":
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    return value


def _validate_limits(limits: object) -> Limits:
    if not isinstance(limits, Limits):
        raise SpoolError("INVALID_INPUT", "limits must be a Limits instance")
    _require_positive_int(limits.max_messages, "max_messages")
    _require_positive_int(limits.max_payload_bytes, "max_payload_bytes")
    _require_positive_int(limits.max_attempts, "max_attempts")
    _require_nonneg_number(limits.lease_seconds, "lease_seconds", positive=True)
    _require_nonneg_number(limits.retry_delay, "retry_delay", positive=False)
    return limits


def _read_clock(clock: Callable[[], Any]) -> float | int:
    try:
        now = clock()
    except Exception as exc:  # noqa: BLE001
        raise SpoolError(
            "INVALID_DEPENDENCY",
            "clock raised",
            {"dependency": "clock", "error": str(exc)},
        ) from exc
    if not _is_finite_number(now):
        raise SpoolError(
            "INVALID_DEPENDENCY",
            "clock must return a finite number",
            {"dependency": "clock"},
        )
    return now


def _canonical_json_bytes(value: object) -> bytes:
    try:
        text = json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        )
    except (TypeError, ValueError) as exc:
        raise SpoolError("INVALID_INPUT", f"payload is not JSON-serializable: {exc}") from exc
    return text.encode("utf-8")


def _state_dumps(state: dict[str, Any]) -> bytes:
    text = json.dumps(
        state,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )
    return (text + "\n").encode("utf-8")


def _public_message(msg: dict[str, Any]) -> dict[str, Any]:
    return {
        "message_id": msg["message_id"],
        "payload": msg["payload"],
        "status": msg["status"],
        "available_at": msg["available_at"],
        "sequence": msg["sequence"],
        "attempts": msg["attempts"],
        "last_error": msg["last_error"],
    }


class _FileLock:
    def __init__(self, path: Path, timeout: float):
        self.path = path
        self.timeout = timeout
        self._fh = None

    def acquire(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        deadline = time.monotonic() + float(self.timeout)
        while True:
            fh = open(self.path, "a+b")
            try:
                if sys.platform == "win32":
                    import msvcrt

                    fh.seek(0)
                    if fh.read(1) == b"":
                        fh.write(b"\0")
                        fh.flush()
                    fh.seek(0)
                    try:
                        msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
                    except OSError:
                        fh.close()
                        if time.monotonic() >= deadline:
                            raise SpoolError("LOCK_TIMEOUT", "lock acquisition timed out")
                        time.sleep(0.01)
                        continue
                else:
                    import fcntl

                    try:
                        fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                    except OSError:
                        fh.close()
                        if time.monotonic() >= deadline:
                            raise SpoolError("LOCK_TIMEOUT", "lock acquisition timed out")
                        time.sleep(0.01)
                        continue
                self._fh = fh
                return
            except SpoolError:
                raise
            except Exception:
                fh.close()
                if time.monotonic() >= deadline:
                    raise SpoolError("LOCK_TIMEOUT", "lock acquisition timed out")
                time.sleep(0.01)

    def release(self) -> None:
        fh = self._fh
        self._fh = None
        if fh is None:
            return
        try:
            if sys.platform == "win32":
                import msvcrt

                fh.seek(0)
                try:
                    msvcrt.locking(fh.fileno(), msvcrt.LK_UNLCK, 1)
                except OSError:
                    pass
            else:
                import fcntl

                try:
                    fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
                except OSError:
                    pass
        finally:
            try:
                fh.close()
            except OSError:
                pass


class Spool:
    """Filesystem-backed lease spool."""

    _SCHEMA_VERSION = 1
    _PUBLIC_STATUSES = frozenset({"pending", "leased", "acked", "dead"})
    _MESSAGE_PUBLIC_KEYS = frozenset(
        {
            "message_id",
            "payload",
            "status",
            "available_at",
            "sequence",
            "attempts",
            "last_error",
        }
    )
    _MESSAGE_PRIVATE_KEYS = frozenset({"lease_token", "worker_id", "expires_at"})
    _TOP_LEVEL_KEYS = frozenset({"schema_version", "next_sequence", "messages"})

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        if not callable(clock):
            raise SpoolError("INVALID_INPUT", "clock must be callable")
        self._limits = _validate_limits(limits)
        if not _is_finite_number(lock_timeout) or float(lock_timeout) < 0:
            raise SpoolError("INVALID_INPUT", "invalid lock_timeout", {"field": "lock_timeout"})
        if failpoint is not None and not callable(failpoint):
            raise SpoolError("INVALID_INPUT", "failpoint must be callable or None")
        self._root = Path(root)
        self._clock = clock
        self._lock_timeout = lock_timeout
        self._failpoint = failpoint
        self._state_path = self._root / "state.json"
        self._lock_path = self._root / "state.lock"
        # Constructor must not write.

    def _call_failpoint(self, name: str) -> None:
        if self._failpoint is None:
            return
        self._failpoint(name)

    def _temp_path(self) -> Path:
        return self._root / f".state.{os.getpid()}.{uuid.uuid4().hex}.tmp"

    def _cleanup_temps(self, extra: Path | None = None) -> None:
        paths = set()
        if extra is not None:
            paths.add(extra)
        try:
            for p in self._root.iterdir():
                name = p.name
                if name.startswith(".state.") and name.endswith(".tmp"):
                    # only own temps: .state.<pid>.<unique>.tmp
                    parts = name.split(".")
                    # ['', 'state', pid, unique, 'tmp'] with leading dot -> name without leading?
                    # name is like .state.123.abc.tmp
                    if name.startswith(f".state.{os.getpid()}."):
                        paths.add(p)
        except OSError:
            pass
        for p in paths:
            try:
                if p.is_file():
                    p.unlink()
            except OSError:
                pass

    def _fsync_dir(self) -> None:
        try:
            if sys.platform == "win32":
                # Directory fsync is not reliably supported on Windows.
                return
            fd = os.open(str(self._root), os.O_RDONLY)
            try:
                os.fsync(fd)
            finally:
                os.close(fd)
        except OSError:
            pass

    def _parse_state_bytes(self, raw: bytes) -> dict[str, Any]:
        if not raw:
            raise SpoolError("CORRUPT_STATE", "empty state file")
        text = raw.decode("utf-8")
        if not text.endswith("\n"):
            raise SpoolError("CORRUPT_STATE", "state must end with newline")
        body = text[:-1]
        # Reject duplicate keys via object_pairs_hook.
        def _pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
            seen: set[str] = set()
            out: dict[str, Any] = {}
            for k, v in pairs:
                if k in seen:
                    raise SpoolError("CORRUPT_STATE", f"duplicate JSON key: {k}")
                seen.add(k)
                out[k] = v
            return out

        try:
            state = json.loads(body, object_pairs_hook=_pairs)
        except SpoolError:
            raise
        except json.JSONDecodeError as exc:
            raise SpoolError("CORRUPT_STATE", f"malformed JSON: {exc}") from exc
        if not isinstance(state, dict):
            raise SpoolError("CORRUPT_STATE", "state root must be object")
        # Canonical form check
        try:
            reencoded = _state_dumps(state)
        except (TypeError, ValueError) as exc:
            raise SpoolError("CORRUPT_STATE", f"non-canonical state: {exc}") from exc
        if reencoded != raw:
            raise SpoolError("CORRUPT_STATE", "state is not canonical JSON")
        self._validate_state(state)
        return state

    def _validate_state(self, state: dict[str, Any]) -> None:
        if set(state.keys()) != self._TOP_LEVEL_KEYS:
            unknown = set(state.keys()) - self._TOP_LEVEL_KEYS
            missing = self._TOP_LEVEL_KEYS - set(state.keys())
            if unknown or missing:
                # unknown schema version handled separately if present
                if "schema_version" in state and state["schema_version"] != self._SCHEMA_VERSION:
                    raise SpoolError(
                        "SCHEMA_MISMATCH",
                        "unknown schema_version",
                        {"schema_version": state.get("schema_version")},
                    )
                raise SpoolError(
                    "CORRUPT_STATE",
                    "invalid top-level fields",
                    {"unknown": sorted(unknown), "missing": sorted(missing)},
                )
        if state["schema_version"] != self._SCHEMA_VERSION:
            raise SpoolError(
                "SCHEMA_MISMATCH",
                "unknown schema_version",
                {"schema_version": state["schema_version"]},
            )
        if _is_bool(state["next_sequence"]) or not isinstance(state["next_sequence"], int):
            raise SpoolError("CORRUPT_STATE", "invalid next_sequence")
        if state["next_sequence"] < 1:
            raise SpoolError("CORRUPT_STATE", "invalid next_sequence")
        messages = state["messages"]
        if not isinstance(messages, dict):
            raise SpoolError("CORRUPT_STATE", "messages must be object")
        max_seq = 0
        for mid, msg in messages.items():
            if not isinstance(mid, str) or not isinstance(msg, dict):
                raise SpoolError("CORRUPT_STATE", "invalid message entry")
            self._validate_message(mid, msg)
            seq = msg["sequence"]
            if seq > max_seq:
                max_seq = seq
        if state["next_sequence"] <= max_seq:
            raise SpoolError("CORRUPT_STATE", "next_sequence inconsistent with messages")

    def _validate_message(self, message_id: str, msg: dict[str, Any]) -> None:
        keys = set(msg.keys())
        allowed = self._MESSAGE_PUBLIC_KEYS | self._MESSAGE_PRIVATE_KEYS
        if not keys.issubset(allowed):
            raise SpoolError(
                "CORRUPT_STATE",
                "unknown message fields",
                {"message_id": message_id},
            )
        required = self._MESSAGE_PUBLIC_KEYS
        if not required.issubset(keys):
            raise SpoolError(
                "CORRUPT_STATE",
                "missing message fields",
                {"message_id": message_id},
            )
        if msg.get("message_id") != message_id:
            raise SpoolError("CORRUPT_STATE", "message_id mismatch")
        status = msg["status"]
        if status not in self._PUBLIC_STATUSES:
            raise SpoolError("CORRUPT_STATE", "invalid status")
        if not _is_finite_number(msg["available_at"]):
            raise SpoolError("CORRUPT_STATE", "invalid available_at")
        if _is_bool(msg["sequence"]) or not isinstance(msg["sequence"], int) or msg["sequence"] < 1:
            raise SpoolError("CORRUPT_STATE", "invalid sequence")
        if _is_bool(msg["attempts"]) or not isinstance(msg["attempts"], int) or msg["attempts"] < 0:
            raise SpoolError("CORRUPT_STATE", "invalid attempts")
        if msg["last_error"] is not None and not isinstance(msg["last_error"], str):
            raise SpoolError("CORRUPT_STATE", "invalid last_error")
        # payload must be JSON types - already loaded
        private = {"lease_token", "worker_id", "expires_at"}
        has_private = private & keys
        if status == "leased":
            if has_private != private:
                raise SpoolError("CORRUPT_STATE", "leased message missing lease fields")
            if not isinstance(msg["lease_token"], str) or not msg["lease_token"]:
                raise SpoolError("CORRUPT_STATE", "invalid lease_token")
            if not isinstance(msg["worker_id"], str) or not msg["worker_id"]:
                raise SpoolError("CORRUPT_STATE", "invalid worker_id")
            if not _is_finite_number(msg["expires_at"]):
                raise SpoolError("CORRUPT_STATE", "invalid expires_at")
        else:
            if has_private:
                raise SpoolError("CORRUPT_STATE", "non-leased message has lease fields")

    def _load_state_unlocked(self) -> dict[str, Any]:
        if not self._state_path.exists():
            raise SpoolError("NOT_INITIALIZED", "spool is not initialized")
        try:
            raw = self._state_path.read_bytes()
        except OSError as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to read state: {exc}") from exc
        return self._parse_state_bytes(raw)

    def _mutate(self, mutator: Callable[[dict[str, Any]], Any], *, require_init: bool = True) -> Any:
        lock = _FileLock(self._lock_path, float(self._lock_timeout))
        tmp: Path | None = None
        lock.acquire()
        try:
            self._call_failpoint("after_lock")
            if require_init:
                if not self._state_path.exists():
                    raise SpoolError("NOT_INITIALIZED", "spool is not initialized")
                state = self._load_state_unlocked()
            else:
                if self._state_path.exists():
                    # validate existing if present
                    try:
                        existing = self._load_state_unlocked()
                    except SpoolError:
                        raise
                    raise SpoolError("ALREADY_INITIALIZED", "spool already initialized")
                state = {
                    "schema_version": self._SCHEMA_VERSION,
                    "next_sequence": 1,
                    "messages": {},
                }

            result = mutator(state)
            # If mutator returns a sentinel for no-write, skip
            if isinstance(result, tuple) and len(result) == 2 and result[0] is _NO_WRITE:
                return result[1]

            raw = _state_dumps(state)
            tmp = self._temp_path()
            with open(tmp, "wb") as fh:
                fh.write(raw)
                fh.flush()
                os.fsync(fh.fileno())
            self._call_failpoint("before_replace")
            os.replace(str(tmp), str(self._state_path))
            tmp = None
            self._call_failpoint("after_replace")
            self._fsync_dir()
            return result
        except Exception:
            raise
        finally:
            self._cleanup_temps(tmp)
            lock.release()

    def initialize(self) -> dict:
        def mutator(state: dict[str, Any]) -> dict:
            return {
                "schema_version": state["schema_version"],
                "next_sequence": state["next_sequence"],
                "messages": {},
            }

        # Special path: already initialized should not overwrite
        lock = _FileLock(self._lock_path, float(self._lock_timeout))
        tmp: Path | None = None
        lock.acquire()
        try:
            self._call_failpoint("after_lock")
            self._root.mkdir(parents=True, exist_ok=True)
            if self._state_path.exists():
                # fail closed on corrupt; ALREADY on valid
                self._load_state_unlocked()
                raise SpoolError("ALREADY_INITIALIZED", "spool already initialized")
            state = {
                "schema_version": self._SCHEMA_VERSION,
                "next_sequence": 1,
                "messages": {},
            }
            raw = _state_dumps(state)
            tmp = self._temp_path()
            with open(tmp, "wb") as fh:
                fh.write(raw)
                fh.flush()
                os.fsync(fh.fileno())
            self._call_failpoint("before_replace")
            os.replace(str(tmp), str(self._state_path))
            tmp = None
            self._call_failpoint("after_replace")
            self._fsync_dir()
            return {
                "schema_version": 1,
                "next_sequence": 1,
                "messages": {},
            }
        finally:
            self._cleanup_temps(tmp)
            lock.release()

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        message_id = _require_nonempty_str(message_id, "message_id")
        payload_bytes = _canonical_json_bytes(payload)
        if len(payload_bytes) > self._limits.max_payload_bytes:
            raise SpoolError(
                "INVALID_INPUT",
                "payload exceeds max_payload_bytes",
                {"size": len(payload_bytes)},
            )
        # Detach payload via round-trip
        detached = json.loads(payload_bytes.decode("utf-8"))

        clock_needed = available_at is None
        if available_at is not None and not _is_finite_number(available_at):
            raise SpoolError("INVALID_INPUT", "invalid available_at", {"field": "available_at"})

        def mutator(state: dict[str, Any]) -> Any:
            messages = state["messages"]
            if message_id in messages:
                existing = messages[message_id]
                avail = available_at
                if clock_needed:
                    # same available_at must match existing; no clock for pure idempotent
                    avail = existing["available_at"]
                # Compare canonical payload and numerically equal available_at
                same_payload = _canonical_json_bytes(existing["payload"]) == payload_bytes
                same_avail = float(existing["available_at"]) == float(avail)  # type: ignore[arg-type]
                if same_payload and same_avail:
                    return _NO_WRITE, _public_message(existing)
                raise SpoolError(
                    "IDEMPOTENCY_CONFLICT",
                    "message_id reused with different request",
                    {"message_id": message_id},
                )
            if len(messages) >= self._limits.max_messages:
                raise SpoolError(
                    "CAPACITY_EXCEEDED",
                    "max_messages exceeded",
                    {"max_messages": self._limits.max_messages},
                )
            if clock_needed:
                avail = _read_clock(self._clock)
            else:
                avail = available_at
            seq = state["next_sequence"]
            state["next_sequence"] = seq + 1
            msg = {
                "message_id": message_id,
                "payload": detached,
                "status": "pending",
                "available_at": avail,
                "sequence": seq,
                "attempts": 0,
                "last_error": None,
            }
            messages[message_id] = msg
            return _public_message(msg)

        return self._mutate(mutator)

    def claim(self, worker_id: str) -> dict | None:
        worker_id = _require_nonempty_str(worker_id, "worker_id")

        def mutator(state: dict[str, Any]) -> Any:
            now = _read_clock(self._clock)
            candidates: list[dict[str, Any]] = []
            for msg in state["messages"].values():
                if msg["status"] == "pending" and float(msg["available_at"]) <= float(now):
                    candidates.append(msg)
            if not candidates:
                return _NO_WRITE, None
            candidates.sort(
                key=lambda m: (float(m["available_at"]), int(m["sequence"]), m["message_id"])
            )
            chosen = candidates[0]
            token = secrets.token_hex(16)
            chosen["status"] = "leased"
            chosen["attempts"] = int(chosen["attempts"]) + 1
            chosen["worker_id"] = worker_id
            chosen["lease_token"] = token
            chosen["expires_at"] = float(now) + float(self._limits.lease_seconds)
            pub = _public_message(chosen)
            pub["lease_token"] = token
            return pub

        return self._mutate(mutator)

    def ack(self, message_id: str, lease_token: str) -> dict:
        message_id = _require_nonempty_str(message_id, "message_id")
        lease_token = _require_nonempty_str(lease_token, "lease_token")

        def mutator(state: dict[str, Any]) -> Any:
            msg = state["messages"].get(message_id)
            if msg is None:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})
            if msg["status"] != "leased":
                raise SpoolError(
                    "UNAUTHORIZED",
                    "message is not leased or token mismatch",
                    {"message_id": message_id},
                )
            expected = msg.get("lease_token", "")
            if not isinstance(expected, str) or not secrets.compare_digest(expected, lease_token):
                raise SpoolError(
                    "UNAUTHORIZED",
                    "message is not leased or token mismatch",
                    {"message_id": message_id},
                )
            msg["status"] = "acked"
            msg.pop("lease_token", None)
            msg.pop("worker_id", None)
            msg.pop("expires_at", None)
            return _public_message(msg)

        return self._mutate(mutator)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        message_id = _require_nonempty_str(message_id, "message_id")
        lease_token = _require_nonempty_str(lease_token, "lease_token")
        error = _require_nonempty_str(error, "error")

        def mutator(state: dict[str, Any]) -> Any:
            msg = state["messages"].get(message_id)
            if msg is None:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})
            if msg["status"] != "leased":
                raise SpoolError(
                    "UNAUTHORIZED",
                    "message is not leased or token mismatch",
                    {"message_id": message_id},
                )
            expected = msg.get("lease_token", "")
            if not isinstance(expected, str) or not secrets.compare_digest(expected, lease_token):
                raise SpoolError(
                    "UNAUTHORIZED",
                    "message is not leased or token mismatch",
                    {"message_id": message_id},
                )
            # authorized - may use clock
            now = _read_clock(self._clock)
            msg["last_error"] = error
            msg.pop("lease_token", None)
            msg.pop("worker_id", None)
            msg.pop("expires_at", None)
            if int(msg["attempts"]) >= self._limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                msg["available_at"] = float(now) + float(self._limits.retry_delay)
            return _public_message(msg)

        return self._mutate(mutator)

    def recover(self) -> dict:
        def mutator(state: dict[str, Any]) -> Any:
            now = _read_clock(self._clock)
            count = 0
            for msg in state["messages"].values():
                if msg["status"] != "leased":
                    continue
                if float(now) < float(msg["expires_at"]):
                    continue
                msg.pop("lease_token", None)
                msg.pop("worker_id", None)
                msg.pop("expires_at", None)
                if int(msg["attempts"]) >= self._limits.max_attempts:
                    msg["status"] = "dead"
                else:
                    msg["status"] = "pending"
                    msg["available_at"] = now
                count += 1
            if count == 0:
                return _NO_WRITE, {"recovered": 0}
            return {"recovered": count}

        return self._mutate(mutator)

    def get(self, message_id: str) -> dict:
        message_id = _require_nonempty_str(message_id, "message_id")

        def mutator(state: dict[str, Any]) -> Any:
            msg = state["messages"].get(message_id)
            if msg is None:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})
            return _NO_WRITE, _public_message(msg)

        return self._mutate(mutator)

    def list_messages(self, status=None) -> list[dict]:
        if status is not None:
            if not isinstance(status, str) or status not in self._PUBLIC_STATUSES:
                raise SpoolError("INVALID_INPUT", "invalid status", {"field": "status"})

        def mutator(state: dict[str, Any]) -> Any:
            items = []
            for msg in state["messages"].values():
                if status is None or msg["status"] == status:
                    items.append(_public_message(msg))
            items.sort(
                key=lambda m: (float(m["available_at"]), int(m["sequence"]), m["message_id"])
            )
            return _NO_WRITE, items

        return self._mutate(mutator)


class _NoWrite:
    pass


_NO_WRITE = _NoWrite()


__all__ = ["Limits", "Spool", "SpoolError"]

display.content:
"""Filesystem-backed durable delivery spool."""

from __future__ import annotations

import dataclasses
import json
import math
import os
import secrets
import sys
import time
import uuid
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable


@dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        self.code = code
        self.message = message
        self.details: dict[str, object] = details if details is not None else {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


def _is_bool(value: object) -> bool:
    return isinstance(value, bool)


def _is_finite_number(value: object) -> bool:
    if _is_bool(value) or not isinstance(value, (int, float)):
        return False
    return math.isfinite(float(value))


def _require_positive_int(value: object, field: str) -> int:
    if _is_bool(value) or not isinstance(value, int) or value <= 0:
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    return value


def _require_nonneg_number(value: object, field: str, *, positive: bool = False) -> float:
    if not _is_finite_number(value):
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    num = float(value) if isinstance(value, float) else value
    if positive and not (num > 0):
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    if not positive and num < 0:
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    return value  # type: ignore[return-value]


def _require_nonempty_str(value: object, field: str) -> str:
    if not isinstance(value, str) or value == "" or value.strip() == "":
        raise SpoolError("INVALID_INPUT", f"invalid {field}", {"field": field})
    return value


def _validate_limits(limits: object) -> Limits:
    if not isinstance(limits, Limits):
        raise SpoolError("INVALID_INPUT", "limits must be a Limits instance")
    _require_positive_int(limits.max_messages, "max_messages")
    _require_positive_int(limits.max_payload_bytes, "max_payload_bytes")
    _require_positive_int(limits.max_attempts, "max_attempts")
    _require_nonneg_number(limits.lease_seconds, "lease_seconds", positive=True)
    _require_nonneg_number(limits.retry_delay, "retry_delay", positive=False)
    return limits


def _read_clock(clock: Callable[[], Any]) -> float | int:
    try:
        now = clock()
    except Exception as exc:  # noqa: BLE001
        raise SpoolError(
            "INVALID_DEPENDENCY",
            "clock raised",
            {"dependency": "clock", "error": str(exc)},
        ) from exc
    if not _is_finite_number(now):
        raise SpoolError(
            "INVALID_DEPENDENCY",
            "clock must return a finite number",
            {"dependency": "clock"},
        )
    return now


def _canonical_json_bytes(value: object) -> bytes:
    try:
        text = json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        )
    except (TypeError, ValueError) as exc:
        raise SpoolError("INVALID_INPUT", f"payload is not JSON-serializable: {exc}") from exc
    return text.encode("utf-8")


def _state_dumps(state: dict[str, Any]) -> bytes:
    text = json.dumps(
        state,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )
    return (text + "\n").encode("utf-8")


def _public_message(msg: dict[str, Any]) -> dict[str, Any]:
    return {
        "message_id": msg["message_id"],
        "payload": msg["payload"],
        "status": msg["status"],
        "available_at": msg["available_at"],
        "sequence": msg["sequence"],
        "attempts": msg["attempts"],
        "last_error": msg["last_error"],
    }


class _FileLock:
    def __init__(self, path: Path, timeout: float):
        self.path = path
        self.timeout = timeout
        self._fh = None

    def acquire(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        deadline = time.monotonic() + float(self.timeout)
        while True:
            fh = open(self.path, "a+b")
            try:
                if sys.platform == "win32":
                    import msvcrt

                    fh.seek(0)
                    if fh.read(1) == b"":
                        fh.write(b"\0")
                        fh.flush()
                    fh.seek(0)
                    try:
                        msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
                    except OSError:
                        fh.close()
                        if time.monotonic() >= deadline:
                            raise SpoolError("LOCK_TIMEOUT", "lock acquisition timed out")
                        time.sleep(0.01)
                        continue
                else:
                    import fcntl

                    try:
                        fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                    except OSError:
                        fh.close()
                        if time.monotonic() >= deadline:
                            raise SpoolError("LOCK_TIMEOUT", "lock acquisition timed out")
                        time.sleep(0.01)
                        continue
                self._fh = fh
                return
            except SpoolError:
                raise
            except Exception:
                fh.close()
                if time.monotonic() >= deadline:
                    raise SpoolError("LOCK_TIMEOUT", "lock acquisition timed out")
                time.sleep(0.01)

    def release(self) -> None:
        fh = self._fh
        self._fh = None
        if fh is None:
            return
        try:
            if sys.platform == "win32":
                import msvcrt

                fh.seek(0)
                try:
                    msvcrt.locking(fh.fileno(), msvcrt.LK_UNLCK, 1)
                except OSError:
                    pass
            else:
                import fcntl

                try:
                    fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
                except OSError:
                    pass
        finally:
            try:
                fh.close()
            except OSError:
                pass


class Spool:
    """Filesystem-backed lease spool."""

    _SCHEMA_VERSION = 1
    _PUBLIC_STATUSES = frozenset({"pending", "leased", "acked", "dead"})
    _MESSAGE_PUBLIC_KEYS = frozenset(
        {
            "message_id",
            "payload",
            "status",
            "available_at",
            "sequence",
            "attempts",
            "last_error",
        }
    )
    _MESSAGE_PRIVATE_KEYS = frozenset({"lease_token", "worker_id", "expires_at"})
    _TOP_LEVEL_KEYS = frozenset({"schema_version", "next_sequence", "messages"})

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        if not callable(clock):
            raise SpoolError("INVALID_INPUT", "clock must be callable")
        self._limits = _validate_limits(limits)
        if not _is_finite_number(lock_timeout) or float(lock_timeout) < 0:
            raise SpoolError("INVALID_INPUT", "invalid lock_timeout", {"field": "lock_timeout"})
        if failpoint is not None and not callable(failpoint):
            raise SpoolError("INVALID_INPUT", "failpoint must be callable or None")
        self._root = Path(root)
        self._clock = clock
        self._lock_timeout = lock_timeout
        self._failpoint = failpoint
        self._state_path = self._root / "state.json"
        self._lock_path = self._root / "state.lock"
        # Constructor must not write.

    def _call_failpoint(self, name: str) -> None:
        if self._failpoint is None:
            return
        self._failpoint(name)

    def _temp_path(self) -> Path:
        return self._root / f".state.{os.getpid()}.{uuid.uuid4().hex}.tmp"

    def _cleanup_temps(self, extra: Path | None = None) -> None:
        paths = set()
        if extra is not None:
            paths.add(extra)
        try:
            for p in self._root.iterdir():
                name = p.name
                if name.startswith(".state.") and name.endswith(".tmp"):
                    # only own temps: .state.<pid>.<unique>.tmp
                    parts = name.split(".")
                    # ['', 'state', pid, unique, 'tmp'] with leading dot -> name without leading?
                    # name is like .state.123.abc.tmp
                    if name.startswith(f".state.{os.getpid()}."):
                        paths.add(p)
        except OSError:
            pass
        for p in paths:
            try:
                if p.is_file():
                    p.unlink()
            except OSError:
                pass

    def _fsync_dir(self) -> None:
        try:
            if sys.platform == "win32":
                # Directory fsync is not reliably supported on Windows.
                return
            fd = os.open(str(self._root), os.O_RDONLY)
            try:
                os.fsync(fd)
            finally:
                os.close(fd)
        except OSError:
            pass

    def _parse_state_bytes(self, raw: bytes) -> dict[str, Any]:
        if not raw:
            raise SpoolError("CORRUPT_STATE", "empty state file")
        text = raw.decode("utf-8")
        if not text.endswith("\n"):
            raise SpoolError("CORRUPT_STATE", "state must end with newline")
        body = text[:-1]
        # Reject duplicate keys via object_pairs_hook.
        def _pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
            seen: set[str] = set()
            out: dict[str, Any] = {}
            for k, v in pairs:
                if k in seen:
                    raise SpoolError("CORRUPT_STATE", f"duplicate JSON key: {k}")
                seen.add(k)
                out[k] = v
            return out

        try:
            state = json.loads(body, object_pairs_hook=_pairs)
        except SpoolError:
            raise
        except json.JSONDecodeError as exc:
            raise SpoolError("CORRUPT_STATE", f"malformed JSON: {exc}") from exc
        if not isinstance(state, dict):
            raise SpoolError("CORRUPT_STATE", "state root must be object")
        # Canonical form check
        try:
            reencoded = _state_dumps(state)
        except (TypeError, ValueError) as exc:
            raise SpoolError("CORRUPT_STATE", f"non-canonical state: {exc}") from exc
        if reencoded != raw:
            raise SpoolError("CORRUPT_STATE", "state is not canonical JSON")
        self._validate_state(state)
        return state

    def _validate_state(self, state: dict[str, Any]) -> None:
        if set(state.keys()) != self._TOP_LEVEL_KEYS:
            unknown = set(state.keys()) - self._TOP_LEVEL_KEYS
            missing = self._TOP_LEVEL_KEYS - set(state.keys())
            if unknown or missing:
                # unknown schema version handled separately if present
                if "schema_version" in state and state["schema_version"] != self._SCHEMA_VERSION:
                    raise SpoolError(
                        "SCHEMA_MISMATCH",
                        "unknown schema_version",
                        {"schema_version": state.get("schema_version")},
                    )
                raise SpoolError(
                    "CORRUPT_STATE",
                    "invalid top-level fields",
                    {"unknown": sorted(unknown), "missing": sorted(missing)},
                )
        if state["schema_version"] != self._SCHEMA_VERSION:
            raise SpoolError(
                "SCHEMA_MISMATCH",
                "unknown schema_version",
                {"schema_version": state["schema_version"]},
            )
        if _is_bool(state["next_sequence"]) or not isinstance(state["next_sequence"], int):
            raise SpoolError("CORRUPT_STATE", "invalid next_sequence")
        if state["next_sequence"] < 1:
            raise SpoolError("CORRUPT_STATE", "invalid next_sequence")
        messages = state["messages"]
        if not isinstance(messages, dict):
            raise SpoolError("CORRUPT_STATE", "messages must be object")
        max_seq = 0
        for mid, msg in messages.items():
            if not isinstance(mid, str) or not isinstance(msg, dict):
                raise SpoolError("CORRUPT_STATE", "invalid message entry")
            self._validate_message(mid, msg)
            seq = msg["sequence"]
            if seq > max_seq:
                max_seq = seq
        if state["next_sequence"] <= max_seq:
            raise SpoolError("CORRUPT_STATE", "next_sequence inconsistent with messages")

    def _validate_message(self, message_id: str, msg: dict[str, Any]) -> None:
        keys = set(msg.keys())
        allowed = self._MESSAGE_PUBLIC_KEYS | self._MESSAGE_PRIVATE_KEYS
        if not keys.issubset(allowed):
            raise SpoolError(
                "CORRUPT_STATE",
                "unknown message fields",
                {"message_id": message_id},
            )
        required = self._MESSAGE_PUBLIC_KEYS
        if not required.issubset(keys):
            raise SpoolError(
                "CORRUPT_STATE",
                "missing message fields",
                {"message_id": message_id},
            )
        if msg.get("message_id") != message_id:
            raise SpoolError("CORRUPT_STATE", "message_id mismatch")
        status = msg["status"]
        if status not in self._PUBLIC_STATUSES:
            raise SpoolError("CORRUPT_STATE", "invalid status")
        if not _is_finite_number(msg["available_at"]):
            raise SpoolError("CORRUPT_STATE", "invalid available_at")
        if _is_bool(msg["sequence"]) or not isinstance(msg["sequence"], int) or msg["sequence"] < 1:
            raise SpoolError("CORRUPT_STATE", "invalid sequence")
        if _is_bool(msg["attempts"]) or not isinstance(msg["attempts"], int) or msg["attempts"] < 0:
            raise SpoolError("CORRUPT_STATE", "invalid attempts")
        if msg["last_error"] is not None and not isinstance(msg["last_error"], str):
            raise SpoolError("CORRUPT_STATE", "invalid last_error")
        # payload must be JSON types - already loaded
        private = {"lease_token", "worker_id", "expires_at"}
        has_private = private & keys
        if status == "leased":
            if has_private != private:
                raise SpoolError("CORRUPT_STATE", "leased message missing lease fields")
            if not isinstance(msg["lease_token"], str) or not msg["lease_token"]:
                raise SpoolError("CORRUPT_STATE", "invalid lease_token")
            if not isinstance(msg["worker_id"], str) or not msg["worker_id"]:
                raise SpoolError("CORRUPT_STATE", "invalid worker_id")
            if not _is_finite_number(msg["expires_at"]):
                raise SpoolError("CORRUPT_STATE", "invalid expires_at")
        else:
            if has_private:
                raise SpoolError("CORRUPT_STATE", "non-leased message has lease fields")

    def _load_state_unlocked(self) -> dict[str, Any]:
        if not self._state_path.exists():
            raise SpoolError("NOT_INITIALIZED", "spool is not initialized")
        try:
            raw = self._state_path.read_bytes()
        except OSError as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to read state: {exc}") from exc
        return self._parse_state_bytes(raw)

    def _mutate(self, mutator: Callable[[dict[str, Any]], Any], *, require_init: bool = True) -> Any:
        lock = _FileLock(self._lock_path, float(self._lock_timeout))
        tmp: Path | None = None
        lock.acquire()
        try:
            self._call_failpoint("after_lock")
            if require_init:
                if not self._state_path.exists():
                    raise SpoolError("NOT_INITIALIZED", "spool is not initialized")
                state = self._load_state_unlocked()
            else:
                if self._state_path.exists():
                    # validate existing if present
                    try:
                        existing = self._load_state_unlocked()
                    except SpoolError:
                        raise
                    raise SpoolError("ALREADY_INITIALIZED", "spool already initialized")
                state = {
                    "schema_version": self._SCHEMA_VERSION,
                    "next_sequence": 1,
                    "messages": {},
                }

            result = mutator(state)
            # If mutator returns a sentinel for no-write, skip
            if isinstance(result, tuple) and len(result) == 2 and result[0] is _NO_WRITE:
                return result[1]

            raw = _state_dumps(state)
            tmp = self._temp_path()
            with open(tmp, "wb") as fh:
                fh.write(raw)
                fh.flush()
                os.fsync(fh.fileno())
            self._call_failpoint("before_replace")
            os.replace(str(tmp), str(self._state_path))
            tmp = None
            self._call_failpoint("after_replace")
            self._fsync_dir()
            return result
        except Exception:
            raise
        finally:
            self._cleanup_temps(tmp)
            lock.release()

    def initialize(self) -> dict:
        def mutator(state: dict[str, Any]) -> dict:
            return {
                "schema_version": state["schema_version"],
                "next_sequence": state["next_sequence"],
                "messages": {},
            }

        # Special path: already initialized should not overwrite
        lock = _FileLock(self._lock_path, float(self._lock_timeout))
        tmp: Path | None = None
        lock.acquire()
        try:
            self._call_failpoint("after_lock")
            self._root.mkdir(parents=True, exist_ok=True)
            if self._state_path.exists():
                # fail closed on corrupt; ALREADY on valid
                self._load_state_unlocked()
                raise SpoolError("ALREADY_INITIALIZED", "spool already initialized")
            state = {
                "schema_version": self._SCHEMA_VERSION,
                "next_sequence": 1,
                "messages": {},
            }
            raw = _state_dumps(state)
            tmp = self._temp_path()
            with open(tmp, "wb") as fh:
                fh.write(raw)
                fh.flush()
                os.fsync(fh.fileno())
            self._call_failpoint("before_replace")
            os.replace(str(tmp), str(self._state_path))
            tmp = None
            self._call_failpoint("after_replace")
            self._fsync_dir()
            return {
                "schema_version": 1,
                "next_sequence": 1,
                "messages": {},
            }
        finally:
            self._cleanup_temps(tmp)
            lock.release()

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        message_id = _require_nonempty_str(message_id, "message_id")
        payload_bytes = _canonical_json_bytes(payload)
        if len(payload_bytes) > self._limits.max_payload_bytes:
            raise SpoolError(
                "INVALID_INPUT",
                "payload exceeds max_payload_bytes",
                {"size": len(payload_bytes)},
            )
        # Detach payload via round-trip
        detached = json.loads(payload_bytes.decode("utf-8"))

        clock_needed = available_at is None
        if available_at is not None and not _is_finite_number(available_at):
            raise SpoolError("INVALID_INPUT", "invalid available_at", {"field": "available_at"})

        def mutator(state: dict[str, Any]) -> Any:
            messages = state["messages"]
            if message_id in messages:
                existing = messages[message_id]
                avail = available_at
                if clock_needed:
                    # same available_at must match existing; no clock for pure idempotent
                    avail = existing["available_at"]
                # Compare canonical payload and numerically equal available_at
                same_payload = _canonical_json_bytes(existing["payload"]) == payload_bytes
                same_avail = float(existing["available_at"]) == float(avail)  # type: ignore[arg-type]
                if same_payload and same_avail:
                    return _NO_WRITE, _public_message(existing)
                raise SpoolError(
                    "IDEMPOTENCY_CONFLICT",
                    "message_id reused with different request",
                    {"message_id": message_id},
                )
            if len(messages) >= self._limits.max_messages:
                raise SpoolError(
                    "CAPACITY_EXCEEDED",
                    "max_messages exceeded",
                    {"max_messages": self._limits.max_messages},
                )
            if clock_needed:
                avail = _read_clock(self._clock)
            else:
                avail = available_at
            seq = state["next_sequence"]
            state["next_sequence"] = seq + 1
            msg = {
                "message_id": message_id,
                "payload": detached,
                "status": "pending",
                "available_at": avail,
                "sequence": seq,
                "attempts": 0,
                "last_error": None,
            }
            messages[message_id] = msg
            return _public_message(msg)

        return self._mutate(mutator)

    def claim(self, worker_id: str) -> dict | None:
        worker_id = _require_nonempty_str(worker_id, "worker_id")

        def mutator(state: dict[str, Any]) -> Any:
            now = _read_clock(self._clock)
            candidates: list[dict[str, Any]] = []
            for msg in state["messages"].values():
                if msg["status"] == "pending" and float(msg["available_at"]) <= float(now):
                    candidates.append(msg)
            if not candidates:
                return _NO_WRITE, None
            candidates.sort(
                key=lambda m: (float(m["available_at"]), int(m["sequence"]), m["message_id"])
            )
            chosen = candidates[0]
            token = secrets.token_hex(16)
            chosen["status"] = "leased"
            chosen["attempts"] = int(chosen["attempts"]) + 1
            chosen["worker_id"] = worker_id
            chosen["lease_token"] = token
            chosen["expires_at"] = float(now) + float(self._limits.lease_seconds)
            pub = _public_message(chosen)
            pub["lease_token"] = token
            return pub

        return self._mutate(mutator)

    def ack(self, message_id: str, lease_token: str) -> dict:
        message_id = _require_nonempty_str(message_id, "message_id")
        lease_token = _require_nonempty_str(lease_token, "lease_token")

        def mutator(state: dict[str, Any]) -> Any:
            msg = state["messages"].get(message_id)
            if msg is None:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})
            if msg["status"] != "leased":
                raise SpoolError(
                    "UNAUTHORIZED",
                    "message is not leased or token mismatch",
                    {"message_id": message_id},
                )
            expected = msg.get("lease_token", "")
            if not isinstance(expected, str) or not secrets.compare_digest(expected, lease_token):
                raise SpoolError(
                    "UNAUTHORIZED",
                    "message is not leased or token mismatch",
                    {"message_id": message_id},
                )
            msg["status"] = "acked"
            msg.pop("lease_token", None)
            msg.pop("worker_id", None)
            msg.pop("expires_at", None)
            return _public_message(msg)

        return self._mutate(mutator)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        message_id = _require_nonempty_str(message_id, "message_id")
        lease_token = _require_nonempty_str(lease_token, "lease_token")
        error = _require_nonempty_str(error, "error")

        def mutator(state: dict[str, Any]) -> Any:
            msg = state["messages"].get(message_id)
            if msg is None:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})
            if msg["status"] != "leased":
                raise SpoolError(
                    "UNAUTHORIZED",
                    "message is not leased or token mismatch",
                    {"message_id": message_id},
                )
            expected = msg.get("lease_token", "")
            if not isinstance(expected, str) or not secrets.compare_digest(expected, lease_token):
                raise SpoolError(
                    "UNAUTHORIZED",
                    "message is not leased or token mismatch",
                    {"message_id": message_id},
                )
            # authorized - may use clock
            now = _read_clock(self._clock)
            msg["last_error"] = error
            msg.pop("lease_token", None)
            msg.pop("worker_id", None)
            msg.pop("expires_at", None)
            if int(msg["attempts"]) >= self._limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                msg["available_at"] = float(now) + float(self._limits.retry_delay)
            return _public_message(msg)

        return self._mutate(mutator)

    def recover(self) -> dict:
        def mutator(state: dict[str, Any]) -> Any:
            now = _read_clock(self._clock)
            count = 0
            for msg in state["messages"].values():
                if msg["status"] != "leased":
                    continue
                if float(now) < float(msg["expires_at"]):
                    continue
                msg.pop("lease_token", None)
                msg.pop("worker_id", None)
                msg.pop("expires_at", None)
                if int(msg["attempts"]) >= self._limits.max_attempts:
                    msg["status"] = "dead"
                else:
                    msg["status"] = "pending"
                    msg["available_at"] = now
                count += 1
            if count == 0:
                return _NO_WRITE, {"recovered": 0}
            return {"recovered": count}

        return self._mutate(mutator)

    def get(self, message_id: str) -> dict:
        message_id = _require_nonempty_str(message_id, "message_id")

        def mutator(state: dict[str, Any]) -> Any:
            msg = state["messages"].get(message_id)
            if msg is None:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})
            return _NO_WRITE, _public_message(msg)

        return self._mutate(mutator)

    def list_messages(self, status=None) -> list[dict]:
        if status is not None:
            if not isinstance(status, str) or status not in self._PUBLIC_STATUSES:
                raise SpoolError("INVALID_INPUT", "invalid status", {"field": "status"})

        def mutator(state: dict[str, Any]) -> Any:
            items = []
            for msg in state["messages"].values():
                if status is None or msg["status"] == status:
                    items.append(_public_message(msg))
            items.sort(
                key=lambda m: (float(m["available_at"]), int(m["sequence"]), m["message_id"])
            )
            return _NO_WRITE, items

        return self._mutate(mutator)


class _NoWrite:
    pass


_NO_WRITE = _NoWrite()


__all__ = ["Limits", "Spool", "SpoolError"]

args.content:
"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time
from typing import Any

from src.delivery_spool import Limits, Spool, SpoolError


def _emit(payload: dict[str, Any], exit_code: int) -> None:
    sys.stdout.write(
        json.dumps(payload, sort_keys=True, separators=(",", ":"), allow_nan=False)
        + "\n"
    )
    sys.stdout.flush()
    raise SystemExit(exit_code)


def _error_payload(code: str, message: str, details: dict[str, object] | None = None) -> dict:
    return {
        "ok": False,
        "error": {
            "code": code,
            "message": message,
            "details": details if details is not None else {},
        },
    }


def _read_input(command: str) -> dict[str, Any]:
    raw = sys.stdin.readline()
    if raw == "" or raw.strip("\n") == "":
        if command in ("init", "recover", "list"):
            return {}
        return {}
    text = raw if not raw.endswith("\n") else raw[:-1]
    if text == "":
        return {}
    try:
        value = json.loads(text)
    except json.JSONDecodeError:
        raise SpoolError("INVALID_INPUT", "stdin must be valid JSON object") from None
    if not isinstance(value, dict):
        raise SpoolError("INVALID_INPUT", "stdin must be a JSON object")
    return value


def _exit_for_code(code: str) -> int:
